const ThumbCard: React.FC<{
  thumb: Thumb;
  index: number;
  width: number;
  highlighted: boolean;
  highlightProgress: number;
}> = ({ thumb, width, highlighted, highlightProgress, index }) => {
  const frame = useCurrentFrame();
  const driftY = ambientDrift(frame, 1.5, 90 + index * 7, `thumb-${index}-y`);
  const driftX = ambientDrift(frame, 1, 110 + index * 5, `thumb-${index}-x`);

  const baseBorder = `1px solid ${COLORS.border}`;
  const hlBorder = `${interpolate(highlightProgress, [0, 1], [1, 3])}px solid ${COLORS.orange}`;
  const border = highlighted ? hlBorder : baseBorder;

  const glowOpacity = highlighted ? highlightProgress * 0.55 : 0;
  const liftScale = highlighted ? 1 + highlightProgress * 0.04 : 1;

  const previewH = width * (9 / 16);
  const metaH = width * 0.22;
  const totalH = previewH + metaH;

  return (
    <div
      style={{
        position: "relative",
        width,
        height: totalH,
        transform: `translate(${driftX}px, ${driftY}px) scale(${liftScale})`,
      }}
    >
      {highlighted && (
        <div
          style={{
            position: "absolute",
            inset: -20,
            background: COLORS.orange,
            filter: "blur(40px)",
            opacity: glowOpacity,
