// ============================================================
// GRID LAYOUT
// ============================================================
function useGridLayout() {
  const { width, height } = useVideoConfig();
  const cols = 3;
  const rows = 3;
  const marginX = width * 0.08;
  const marginY = height * 0.1;
  const gapX = width * 0.035;
  const gapY = height * 0.06;

  const availH = height - marginY * 2 - gapY * (rows - 1);
  const cardAspectH = 9 / 16 + 0.22;
  const cellHByHeight = availH / rows;
  const cellWByHeight = cellHByHeight / cardAspectH;

  const availW = width - marginX * 2 - gapX * (cols - 1);
  const cellWByWidth = availW / cols;

  const cellW = Math.min(cellWByWidth, cellWByHeight);
  const cellH = cellW * cardAspectH;

  const gridW = cellW * cols + gapX * (cols - 1);
  const gridH = cellH * rows + gapY * (rows - 1);

  return {
    cols,
    rows,
    cellW,
    cellH,
    gapX,
    gapY,
    gridW,
    gridH,
    offsetX: (width - gridW) / 2,
    offsetY: (height - gridH) / 2,
  };
}

// ============================================================
// SINGLE SCENE — grid is fully ready at frame 0, highlights kick in at frame 17
// ============================================================
const SceneMain: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { cols, cellW, cellH, gapX, gapY, gridW, gridH, offsetX, offsetY } = useGridLayout();

  // Highlights begin at frame 17 (00:00:00:17). Quick stagger between the 3.
  const HL_START = 17;
  const HL_STAGGER = 4; // tight, snappy cascade

  // Subtle breathing on highlighted cards once they've fully landed
  const breathePulse = Math.sin(frame / 22) * 0.08;

  return (
    <AbsoluteFill>
      <Background />

      <div
        style={{
          position: "absolute",
          left: offsetX,
          top: offsetY,
          width: gridW,
          height: gridH,
          display: "grid",
          gridTemplateColumns: `repeat(${cols}, ${cellW}px)`,
          gridAutoRows: `${cellH}px`,
          columnGap: gapX,
          rowGap: gapY,
        }}
      >
        {THUMBS.map((thumb, i) => {
          const isHighlighted = HIGHLIGHT_INDICES.includes(i);
          const hlOrder = HIGHLIGHT_INDICES.indexOf(i);

          // Snappy entrance for the orange highlight ring/glow
          const hlEntrance = isHighlighted
            ? springIn(frame, fps, HL_START + hlOrder * HL_STAGGER, "SNAPPY")
            : 0;

          // Add a gentle breathing once fully entered
          const hlProgress = isHighlighted
            ? Math.min(1, hlEntrance + breathePulse * hlEntrance)
            : 0;

          // Non-highlighted cards dim slightly after highlights kick in
          const dimStart = HL_START + 2;
          const dimT = !isHighlighted
            ? interpolate(frame, [dimStart, dimStart + 14], [1, 0.35], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })
            : 1;

          return (
            <div
              key={thumb.id}
              style={{
                opacity: dimT,
                position: "relative",
                zIndex: isHighlighted ? 2 : 1,
              }}
            >
              <ThumbCard
                thumb={thumb}
                index={i}
                width={cellW}
                highlighted={isHighlighted}
                highlightProgress={hlProgress}
              />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

